import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's rates, then its parents' (see {@link RateRepository#chain}). Viewed as of a date, each sheet up the
 *  chain is read as it stood at the end of that date: a sheet's view holds only its own rows, so its parents are each
 *  read in their own. */
public class RespondWithRates {
    public void respond(@Val SheetResponse sheet, @Val ViewAsOf asOf, SheetHistory history,
            ObjectResponse<List<RateResponse>> response) {
        if (asOf.on() == null) {
            response.send(history.view(sheet.id(), null, jdbc -> new RateRepository(jdbc).chain(sheet.id()).stream()
                    .map(RateResponse::from).toList()));
            return;
        }
        List<String> seen = new ArrayList<>();
        List<Rate> found = new ArrayList<>();
        String at = sheet.id();
        while (at != null && !seen.contains(at) && seen.size() <= RateRepository.PARENT_LEVELS) {
            String id = at;
            int level = seen.size();
            seen.add(id);
            Map.Entry<List<Rate>, String> read = history.view(id, asOf.on(), jdbc -> {
                RateRepository rates = new RateRepository(jdbc);
                return new java.util.AbstractMap.SimpleEntry<>(rates.list(id), rates.parentOf(id));
            });
            read.getKey().forEach(r -> found.add(r.at(level)));
            at = read.getValue();
        }
        response.send(found.stream().map(RateResponse::from).toList());
    }
}

